import{_ as n,C as s,o as i,c as r,a2 as h,E as l,j as t,a}from"./chunks/framework.CHjbm2Wd.js";const y=JSON.parse('{"title":"How to use this guide","description":"The study loop, page anatomy, and how to turn reading into flight-software skill.","frontmatter":{"title":"How to use this guide","description":"The study loop, page anatomy, and how to turn reading into flight-software skill."},"headers":[],"relativePath":"start/how-to-use.md","filePath":"start/how-to-use.md","lastUpdated":1792993690000}'),d={name:"start/how-to-use.md"};function u(c,e,p,m,g,f){const o=s("Quiz");return i(),r("div",null,[e[0]||(e[0]=h('<h1 id="how-to-use-this-guide" tabindex="-1">How to use this guide <a class="header-anchor" href="#how-to-use-this-guide" aria-label="Permalink to &quot;How to use this guide&quot;">​</a></h1><p>You are a developer moving into a domain where a units mistake can crash a lander. Reading alone will not get you there. The site is built around a loop:</p><p><strong>Read → build → explain → test.</strong></p><p>Each topic page is short enough to finish in one sitting and structured so you cannot mistake “I read it” for “I can use it.”</p><h2 id="the-90-minute-study-loop" tabindex="-1">The 90-minute study loop <a class="header-anchor" href="#the-90-minute-study-loop" aria-label="Permalink to &quot;The 90-minute study loop&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Step</th><th>Time</th><th>What you actually do</th></tr></thead><tbody><tr><td>Read</td><td>20 min</td><td>Read the page once, without taking notes. Mark the two or three ideas that feel unstable.</td></tr><tr><td>Build</td><td>35 min</td><td>Do the practice task. Type the code, run the sim, or draw the frames. Do not copy-paste.</td></tr><tr><td>Explain</td><td>15 min</td><td>Close the page and explain the core idea in your own words, on paper or out loud.</td></tr><tr><td>Test</td><td>20 min</td><td>Answer the quiz, then re-do the exercise from scratch or change one assumption.</td></tr></tbody></table><p>If a page takes less than an hour, you probably skimmed it. If it takes more than three, you are trying to learn the references instead of the concept. Move on and come back.</p><h2 id="page-anatomy" tabindex="-1">Page anatomy <a class="header-anchor" href="#page-anatomy" aria-label="Permalink to &quot;Page anatomy&quot;">​</a></h2><p>Most topic pages use the same shape:</p><ul><li><strong>Why this matters</strong> — where the topic appears in a lunar lander program.</li><li><strong>Learning objectives</strong> — what you should be able to do, not just recognize.</li><li><strong>Core notes</strong> — the minimum model, vocabulary, equations, and failure modes.</li><li><strong>Flight-software lens</strong> — how the concept becomes code, interfaces, timing, and tests.</li><li><strong>Practice</strong> — an exercise with a concrete output.</li><li><strong>Quiz</strong> — a quick check, with an explanation.</li><li><strong>Resources</strong> — where to go deeper.</li></ul><p>Pages marked <strong>Core</strong> in the sidebar and progress dashboard are the deep dives. The rest are orientation pages: enough to read the documentation, ask a useful question, and know what to learn next.</p><h2 id="what-done-means" tabindex="-1">What “done” means <a class="header-anchor" href="#what-done-means" aria-label="Permalink to &quot;What “done” means&quot;">​</a></h2><p>A topic is done when you can do three things:</p><ol><li><strong>Draw it.</strong> Sketch the frames, signal flow, state machine, or control loop from memory.</li><li><strong>Implement it.</strong> Write a small version that runs and produces a number or plot you can check.</li><li><strong>Defend it.</strong> Explain the assumptions, failure modes, and test evidence to someone who will interrupt you.</li></ol><p>Marking a page complete is a bookmark, not proof. The exercises are the proof.</p><h2 id="use-the-llv-console-as-the-lab" tabindex="-1">Use the LLV console as the lab <a class="header-anchor" href="#use-the-llv-console-as-the-lab" aria-label="Permalink to &quot;Use the LLV console as the lab&quot;">​</a></h2><p>You already have a lunar-lander UI and a simulation seam in the <code>Vault</code> project. Use it:</p><ul><li>Studying frames? Add a frame label to every state in the console.</li><li>Studying quaternions? Replace the single tilt axis with a full attitude state and show the body axes.</li><li>Studying 6DOF? Implement gravity, translation, mass flow, and a fixed-step integrator behind <code>stepState()</code>.</li><li>Studying navigation? Add a noisy IMU and altimeter, then estimate altitude and vertical speed.</li><li>Studying guidance? Generate a throttle and attitude command instead of reading them from the keyboard.</li><li>Studying V&amp;V? Write a test that proves the lander does not go below the surface.</li></ul><p>The <a href="./../mission/llv-bridge.html">LLV bridge page</a> maps every module to a concrete next step in that project.</p><h2 id="what-to-skip-and-when" tabindex="-1">What to skip, and when <a class="header-anchor" href="#what-to-skip-and-when" aria-label="Permalink to &quot;What to skip, and when&quot;">​</a></h2><p>You do not need everything in Month 1 to start Month 2.</p><ul><li>If you already use Git daily, skim the Git page and spend the time on CMake and debugging.</li><li>If you have never used MATLAB, do the Simulink orientation but do not become a MATLAB language expert.</li><li>If STK is slow or awkward on your machine, build the scenario once, then move on. The concepts matter more than the UI.</li><li>Do not start with the full three-body problem, propulsion thermodynamics, or sensor hardware design. They are not on the critical path for a flight-software role.</li></ul><h2 id="a-note-on-sources" tabindex="-1">A note on sources <a class="header-anchor" href="#a-note-on-sources" aria-label="Permalink to &quot;A note on sources&quot;">​</a></h2><p>The pages are original summaries written for this path. Equations and conventions are standard, but missions differ. When you work on a real program, the controlling documents are the interface control document, the software requirements specification, the flight software users&#39; guide, and the mission operations handbook. This site teaches the vocabulary and the engineering habits that let you read those documents.</p><h2 id="the-weekly-cadence" tabindex="-1">The weekly cadence <a class="header-anchor" href="#the-weekly-cadence" aria-label="Permalink to &quot;The weekly cadence&quot;">​</a></h2><p>A sustainable week looks like this:</p><ul><li><strong>Two study sessions</strong> of 90 minutes for new material.</li><li><strong>One build session</strong> of 2 hours for the week&#39;s exercise.</li><li><strong>One review session</strong> of 45 minutes for last week&#39;s quiz and notes.</li><li><strong>One short write-up</strong> of what broke, what you fixed, and what you still do not understand.</li></ul><p>That is roughly 6–8 hours. The roadmap assumes 12–15 hours, so scale the number of sessions, not the depth of the build.</p>',28)),l(o,{question:"You finish reading a page and the quiz feels easy. What is the best next step?",options:"Mark it complete and start the next page|Close the page and rebuild the exercise from scratch, then change one assumption|Read the linked references until you understand every derivation|Watch a video on the same topic",answer:"1",explanation:"Recognition is not recall. Rebuilding the exercise and perturbing it is the cheapest test of whether the model is actually yours."}),e[1]||(e[1]=t("p",null,[a("Next: "),t("a",{href:"./roadmap.html"},"the 16-week roadmap"),a(" or "),t("a",{href:"./setup.html"},"set up your tools"),a(".")],-1))])}const b=n(d,[["render",u]]);export{y as __pageData,b as default};
